DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['internet_providers','internet_provider_accounts','internet_collection_runs','internet_collection_jobs','internet_contracts','internet_contract_buildings','internet_invoices','internet_invoice_observations','internet_invoice_payments','internet_documents','internet_exceptions','internet_audit_events'] LOOP EXECUTE format('REVOKE ALL ON public.%I FROM authenticated',t); IF t <> 'internet_provider_accounts' THEN EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t); END IF; END LOOP; END $$; GRANT SELECT (id,provider_id,holder_name,holder_document,account_label,external_account_id,enabled,access_state,created_at,updated_at) ON public.internet_provider_accounts TO authenticated;